REQUIREMENTS = "pandas>=1.5\nopenpyxl>=3.0\n"

_SRC = {
    'keybank_style': KEYBANK_STYLE_B64,
    'series_seed': SERIES_SEED_B64,
    'runner': RUNNER_B64,
    'vba_writer': VBA_WRITER_B64,
    'assemble_xlsm': ASSEMBLE_XLSM_B64,
    'build_workbook': BUILD_WORKBOOK_B64,
}

def _decode(b): return gzip.decompress(base64.b64decode(b)).decode("utf-8")

def _write(path, text):
    with open(path, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(text)

def main():
    cwd = os.getcwd()
    # 1) drop the files the refresh/fallback flows need
    _write(os.path.join(cwd, "runner.py"), _decode(_SRC["runner"]))
    _write(os.path.join(cwd, "macro.bas"), _decode(MACRO_B64))
    _write(os.path.join(cwd, "requirements.txt"), REQUIREMENTS)
    # 2) register modules from embedded source (no imports from disk)
    for name in ('keybank_style', 'series_seed', 'runner', 'vba_writer', 'assemble_xlsm', 'build_workbook'):
        m = types.ModuleType(name)
        m.__file__ = os.path.join(cwd, name + ".py")
        sys.modules[name] = m
        exec(compile(_decode(_SRC[name]), name + ".py", "exec"), m.__dict__)
    # 3) build base workbook -> embed VBA -> demo-populate the .xlsm
    base = os.path.join(cwd, "Mortgage_Delinquency_Monitor_fallback.xlsx")
    out = os.path.join(cwd, "Mortgage_Delinquency_Monitor.xlsm")
    sys.modules["build_workbook"].build(base)
    sys.modules["assemble_xlsm"].assemble(base, out,
        macro_bas=os.path.join(cwd, "macro.bas"))
    sys.modules["runner"].run(out, demo=True)
    # 4) demo-populate the fallback too, so it opens showing dashboards
    sys.modules["runner"].run(base, demo=True)
    print("Built:", out)
    print("Fallback (no VBA):", base)
    print("Also wrote runner.py, macro.bas, requirements.txt in", cwd)
    print("Open the .xlsm (enable macros). If Excel rejects it, open the")
    print("fallback .xlsx, paste macro.bas via Alt+F11, save as .xlsm.")
    print("Live CFPB pulls are KEYLESS -- public domain, no account needed.")

if __name__ == "__main__":
    try:
        main()
    except ImportError as e:
        sys.stderr.write("Missing dependency: %s\nRun: python -m pip install pandas openpyxl\n" % e)
        sys.exit(1)
